function gmNorm(PDO $p,array $tables):array{$out=[];foreach($tables as$table){$order=$table==='gift_code_counts'?'campaign_id,player_id':($table==='player_values'?'user_id':'id');$rows=$p->query('SELECT * FROM '.$table.' ORDER BY '.$order)->fetchAll(PDO::FETCH_ASSOC);foreach($rows as&$row){foreach($row as$key=>&$value)if($value!==null){if(($table==='gift_codes'&&$key==='v2_id')||($table==='gift_code_counts'&&in_array($key,['campaign_id','player_id'],true)))$value=['binary'=>base64_encode($value)];else$value=(string)$value;}unset($value);ksort($row,SORT_STRING);}unset($row);$out[$table]=$rows;}return$out;}
