    // Actually restore the logical fixture snapshot into another database and compare every column.
    $restore=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$restore->exec(file_get_contents(__DIR__.'/../migrations/sqlite.sql'));
    foreach($snapshot as$table=>$rows)foreach($rows as$row){$q=$restore->prepare('INSERT INTO '.$table.'('.implode(',',array_keys($row)).') VALUES('.implode(',',array_fill(0,count($row),'?')).')');$i=1;foreach($row as$value){if(is_array($value))$q->bindValue($i++,base64_decode($value['binary']),PDO::PARAM_LOB);else$q->bindValue($i++,$value,$value===null?PDO::PARAM_NULL:PDO::PARAM_STR);}$q->execute();}
    $equal=gmNorm($restore,$tables)===$snapshot;gmCheck(true,$equal,'actual backup restoration/readback');$proof=$directory.'/restore-'.Database::uuid().'.json';file_put_contents($proof,json_encode(['restoredEqual'=>$equal,'snapshotSha256'=>hash('sha256',json_encode($snapshot,JSON_THROW_ON_ERROR))]));
    $provenance=$directory.'/provenance-'.Database::uuid().'.json';file_put_contents($provenance,json_encode(['sourceCampaignId'=>$source,'usedCount'=>$used,'sourceCommit'=>'d27c1b1c377a1d6ab14f7a4244628f4386707564','monotoneHistoryVerified'=>true,'writersStopped'=>true]));$e=[];foreach(['backup'=>$backup,'restoreProof'=>$proof,'provenance'=>$provenance]as$key=>$path)$e[$key]=['path'=>$path,'sha256'=>hash_file('sha256',$path)];return$e;
}
